describe('Card Payment Form - Successful Purchase', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully complete purchase with valid card details', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments/create').as('paymentRequest');

    // Fill in card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Verify fields are filled
    cy.get('[data-testid="card-number-input"]').should('have.value', '4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '12/25');
    cy.get('[data-testid="card-cvc-input"]').should('have.value', '123');

    // Verify card validation message is not displayed
    cy.get('[data-testid="card-validation-message"]').should('not.exist');

    // Click the submit button
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API call
    cy.wait('@paymentRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Payment successful');

    // Verify cart is cleared
    cy.get('[data-testid="cart-item-count"]').should('contain', '0');

    // Verify order confirmation page is displayed
    cy.url().should('include', '/order/confirmation');
  });

  it('should handle invalid card details and display error message', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payments/create').as('paymentRequest');

    // Fill in invalid card details
    cy.get('[data-testid="card-number-input"]').type('1234567890123456');
    cy.get('[data-testid="card-expiry-input"]').type('01/20');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Verify fields are filled
    cy.get('[data-testid="card-number-input"]').should('have.value', '1234567890123456');
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '01/20');
    cy.get('[data-testid="card-cvc-input"]').should('have.value', '123');

    // Verify card validation message is displayed
    cy.get('[data-testid="card-validation-message"]').should('be.visible').should('contain', 'Invalid card number');

    // Click the submit button
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API call
    cy.wait('@paymentRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid card details');

    // Verify cart is not cleared
    cy.get('[data-testid="cart-item-count"]').should('contain', '1');

    // Verify user can retry
    cy.get('[data-testid="retry-button"]').should('be.visible').click();

    // Verify card validation message disappears
    cy.get('[data-testid="card-validation-message"]').should('not.exist');

    // Verify user can enter new card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111117');
    cy.get('[data-testid="card-expiry-input"]').type('12/25');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Verify card validation message is not displayed
    cy.get('[data-testid="card-validation-message"]').should('not.exist');

    // Click the submit button again
    cy.get('[data-testid="submit-payment-btn"]').click();

    // Wait for payment API call
    cy.wait('@paymentRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Payment successful');

    // Verify cart is cleared
    cy.get('[data-testid="cart-item-count"]').should('contain', '0');
  });
});
